"""
CloneCinema — Kernel Wan 2.1 I2V con Frame Chaining (Micro-Storyboards Continuos).
Genera múltiples escenas consecutivas tomando el último frame del clip precedente como semilla.
"""

import subprocess
import sys
import os

try:
    import ftfy  # pyrefly: ignore[missing-import] # type: ignore
except ImportError:
    subprocess.run([sys.executable, "-m", "pip", "install", "ftfy", "-q"])
    import ftfy  # pyrefly: ignore[missing-import] # type: ignore

import builtins
builtins.ftfy = ftfy

try:
    import diffusers.pipelines.wan.pipeline_wan_i2v as _wan_i2v_mod  # pyrefly: ignore[missing-import] # type: ignore
    _wan_i2v_mod.ftfy = ftfy
except Exception:
    pass

import base64
import gc
import io
import json
import time

os.environ["PYTORCH_CUDA_ALLOC_CONF"] = "expandable_segments:True"

try:
    import torch  # pyrefly: ignore[missing-import] # type: ignore
    from diffusers import WanImageToVideoPipeline  # pyrefly: ignore[missing-import] # type: ignore
    from diffusers.utils import export_to_video, load_image  # pyrefly: ignore[missing-import] # type: ignore
    from PIL import Image  # pyrefly: ignore[missing-import] # type: ignore
    import numpy as np  # pyrefly: ignore[missing-import] # type: ignore
except ImportError:
    torch = None  # type: ignore
    WanImageToVideoPipeline = None  # type: ignore

PAYLOAD = json.loads(base64.b64decode("").decode("utf-8"))

I2V_MODEL = PAYLOAD.get("model_id") or os.environ.get(
    "WAN_MODEL_ID", "engineerA314/Wan2.1-Fun-V1.1-1.3B-InP-Diffusers"
)

SIZES = {
    "9:16": (480, 832),
    "16:9": (832, 480),
    "1:1": (480, 480),
    "safe_16:9": (640, 384),
    "safe_9:16": (384, 640),
}

NEGATIVE_PROMPT = (
    "Bright tones, overexposed, static, blurred details, subtitles, watermark, "
    "worst quality, low quality, JPEG artifacts, deformed, disfigured, "
    "extra limbs, fused fingers, still picture, messy background"
)


def clamp_frames(frames: int) -> int:
    frames = max(17, min(int(frames), 41))
    return frames - ((frames - 1) % 4)


def load_pipeline():
    print(f"[clonecinema] Cargando modelo Wan I2V ({I2V_MODEL}) en torch.float16...")
    try:
        pipe = WanImageToVideoPipeline.from_pretrained(
            I2V_MODEL, torch_dtype=torch.float16
        )
    except Exception as e:
        print(f"[clonecinema] Fallback carga modular: {e}")
        from diffusers import AutoencoderKLWan  # pyrefly: ignore[missing-import] # type: ignore
        from transformers import CLIPVisionModel  # pyrefly: ignore[missing-import] # type: ignore
        image_encoder = CLIPVisionModel.from_pretrained(
            I2V_MODEL, subfolder="image_encoder", torch_dtype=torch.float16
        )
        vae = AutoencoderKLWan.from_pretrained(I2V_MODEL, subfolder="vae", torch_dtype=torch.float16)
        pipe = WanImageToVideoPipeline.from_pretrained(
            I2V_MODEL, vae=vae, image_encoder=image_encoder, torch_dtype=torch.float16
        )

    if hasattr(pipe, "enable_vae_tiling"):
        pipe.enable_vae_tiling()
    if hasattr(pipe, "enable_vae_slicing"):
        pipe.enable_vae_slicing()

    pipe.enable_sequential_cpu_offload()
    gc.collect()
    torch.cuda.empty_cache()
    return pipe


def main() -> None:
    started_total = time.time()
    aspect = PAYLOAD.get("aspect_ratio") or "safe_9:16"
    width, height = SIZES.get(aspect, SIZES["safe_9:16"])
    frames_per_clip = clamp_frames(PAYLOAD.get("num_frames") or 33)
    fps = int(PAYLOAD.get("fps") or 16)

    pipe = load_pipeline()

    chain_prompts = PAYLOAD.get("chain_prompts")
    if not chain_prompts:
        chain_prompts = [PAYLOAD.get("prompt") or "A cute character smiling, smooth motion"]

    # Imagen inicial
    initial_b64 = PAYLOAD.get("initial_image_b64") or PAYLOAD.get("image_b64")
    if not initial_b64:
        raise SystemExit("Se requiere initial_image_b64 para I2V Chaining.")

    raw_img = Image.open(io.BytesIO(base64.b64decode(initial_b64))).convert("RGB")
    current_image = load_image(raw_img.resize((width, height), Image.Resampling.LANCZOS))

    master_frames = []
    clip_records = []

    print(f"[clonecinema] Iniciando Frame Chaining de {len(chain_prompts)} clips consecutivos ({width}x{height}, {fps}fps)...")

    for idx, prompt in enumerate(chain_prompts):
        clip_num = idx + 1
        t_start = time.time()
        print(f"\n--- [Clip {clip_num}/{len(chain_prompts)}] ---")
        print(f"Prompt: {prompt[:200]}")

        # Inferencia I2V
        output = pipe(
            image=current_image,
            prompt=prompt,
            negative_prompt=NEGATIVE_PROMPT,
            height=height,
            width=width,
            num_frames=frames_per_clip,
            guidance_scale=5.0,
        )

        clip_frames = output.frames[0]
        clip_path = f"/kaggle/working/clip_{clip_num}.mp4"
        export_to_video(clip_frames, clip_path, fps=fps)

        dur_clip = round(time.time() - t_start, 1)
        print(f"[clonecinema] Clip {clip_num} completado en {dur_clip}s -> {clip_path}")

        # Guardar en la secuencia maestra
        if idx == 0:
            master_frames.extend(clip_frames)
        else:
            # Omitimos el frame [0] para evitar congelamiento de 1 cuadro en la costura
            master_frames.extend(clip_frames[1:])

        # El último frame se convierte en el ancla del siguiente clip
        last_frame_raw = clip_frames[-1]
        if isinstance(last_frame_raw, Image.Image):
            last_frame_pil = last_frame_raw
        else:
            arr = np.array(last_frame_raw)
            if arr.dtype in [np.float32, np.float64]:
                arr = (np.clip(arr, 0.0, 1.0) * 255.0).astype(np.uint8)
            last_frame_pil = Image.fromarray(arr)
        
        current_image = load_image(last_frame_pil.resize((width, height), Image.Resampling.LANCZOS))
        current_image.save(f"/kaggle/working/last_frame_clip_{clip_num}.png")

        clip_records.append({
            "clip": clip_num,
            "seconds": dur_clip,
            "prompt": prompt,
            "frames": len(clip_frames)
        })

        gc.collect()
        torch.cuda.empty_cache()

    # Exportar video maestro continuo ensamblado
    master_path = "/kaggle/working/output_video.mp4"
    export_to_video(master_frames, master_path, fps=fps)
    total_time = round(time.time() - started_total, 1)

    print(f"\n[clonecinema] 🎉 SECUENCIA COMPLETA ENSAMBLADA en {total_time}s -> {master_path}")
    print(f"Total fotogramas continuos: {len(master_frames)} (~{round(len(master_frames)/fps, 1)}s)")

    with open("/kaggle/working/result.json", "w", encoding="utf-8") as fh:
        json.dump(
            {
                "job_id": PAYLOAD.get("job_id"),
                "mode": "chained_i2v",
                "clips_count": len(chain_prompts),
                "total_frames": len(master_frames),
                "total_duration_sec": round(len(master_frames) / fps, 1),
                "total_render_seconds": total_time,
                "clips": clip_records
            },
            fh,
            indent=2
        )


if __name__ == "__main__":
    main()
